#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#else
#define VW 8
#endif

typedef float vf __attribute__((vector_size(VW * 4)));

#define MR 6
#define NR (2 * VW)
#define KC 256
#define MC 72
#define NCB 192

static inline __attribute__((always_inline)) vf ldu(const float *p) {
    vf v;
    memcpy(&v, p, sizeof(vf));
    return v;
}
static inline __attribute__((always_inline)) void stu(float *p, vf v) {
    memcpy(p, &v, sizeof(vf));
}

static inline __attribute__((always_inline)) void kern(int kc, const float *a, const float *b,
                                                      float *c, int ldc, int acc) {
    vf c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    vf c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};
    for (int p = 0; p < kc; p++) {
        vf b0 = ((const vf *)b)[0];
        vf b1 = ((const vf *)b)[1];
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }
#define ST(r, x0, x1)                                                  \
    do {                                                               \
        float *cr = c + (size_t)(r) * ldc;                             \
        if (acc) { x0 += ldu(cr); x1 += ldu(cr + VW); }                \
        stu(cr, x0); stu(cr + VW, x1);                                 \
    } while (0)
    ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
    ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
}

void matmul(const float *A, const float *B, float *C, int n) {
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    size_t bsz = (size_t)KC * npan * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);
    int nib = (n + MC - 1) / MC, njb = (n + NCB - 1) / NCB;
    int ntiles = nib * njb;

#pragma omp parallel
    {
        float *Ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));
        float tmp[MR * NR] __attribute__((aligned(64)));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc > 0;

#pragma omp for schedule(static)
            for (int jp = 0; jp < npan; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                for (int p = 0; p < kc; p++) {
                    const float *src = B + (size_t)(pc + p) * n + j0;
                    float *d = dst + (size_t)p * NR;
                    int c = 0;
                    for (; c < nr; c++) d[c] = src[c];
                    for (; c < NR; c++) d[c] = 0.0f;
                }
            }

#pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntiles; t++) {
                int ib = t / njb, jb = t % njb;
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int j0 = jb * NCB;
                int nc = n - j0 < NCB ? n - j0 : NCB;

                for (int ir = 0; ir < mc; ir += MR) {
                    float *d = Ap + (size_t)(ir / MR) * kc * MR;
                    int mr = mc - ir < MR ? mc - ir : MR;
                    const float *src = A + (size_t)(i0 + ir) * n + pc;
                    for (int p = 0; p < kc; p++) {
                        int r = 0;
                        for (; r < mr; r++) d[p * MR + r] = src[(size_t)r * n + p];
                        for (; r < MR; r++) d[p * MR + r] = 0.0f;
                    }
                }

                for (int jr = j0; jr < j0 + nc; jr += NR) {
                    int nr = j0 + nc - jr < NR ? j0 + nc - jr : NR;
                    const float *bpan = Bp + (size_t)(jr / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        const float *apan = Ap + (size_t)(ir / MR) * kc * MR;
                        float *cp = C + (size_t)(i0 + ir) * n + jr;
                        if (mr == MR && nr == NR) {
                            kern(kc, apan, bpan, cp, n, acc);
                        } else {
                            kern(kc, apan, bpan, tmp, NR, 0);
                            for (int r = 0; r < mr; r++) {
                                float *crow = cp + (size_t)r * n;
                                const float *trow = tmp + r * NR;
                                if (acc)
                                    for (int c = 0; c < nr; c++) crow[c] += trow[c];
                                else
                                    for (int c = 0; c < nr; c++) crow[c] = trow[c];
                            }
                        }
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
